+    private string? submitError;
+
+    private void GoToStep(int step)
+    {
+        if (completedSteps.Contains(step) || step == currentStep)
+            currentStep = step;
+    }
+
+    private void GoBack()
+    {
+        if (currentStep > 0)
+            currentStep--;
+    }
+
+    private Task<bool> ValidateEmailAsync(string email) =>
+        ApplicationService.ValidateEmailAsync(email);
+
+    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
+    {
+        personalInfoResult = result;
+        personalInfo = (result.FullName, result.Email, result.Phone, result.Address);
+        completedSteps.Add(0);
+        currentStep = 1;
+    }
+
+    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
+    {
+        workEntries = entries;
+        completedSteps.Add(1);
+        currentStep = 2;
+    }
+
+    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
+    {
+        references = refs;
+        completedSteps.Add(2);
+        currentStep = 3;
+    }
+
+    private void HandleCoverLetterNext(string text)
+    {
+        coverLetter = text;
+        completedSteps.Add(3);
+        currentStep = 4;
+    }
+
+    private async Task HandleSubmit()
+    {
+        isSubmitting = true;
+        submitError = null;
+
+        try
+        {
+            var workHistory = new WorkHistory(workEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList());
+
+            var refList = references.Select(r =>
+                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+
+            var personal = new PersonalInfo(
+                personalInfoResult.FullName,
+                personalInfoResult.Email,
+                personalInfoResult.Phone,
+                personalInfoResult.Address);
+
+            var application = new JobApplication(personal, workHistory, refList, coverLetter);
+            applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            isSubmitted = true;
+            completedSteps.Add(4);
+        }
+        catch (Exception ex)
+        {
+            submitError = $"Submission failed: {ex.Message}. Please try again.";
+        }
+        finally
+        {
+            isSubmitting = false;
+        }
+    }
+}
