+
+.form-control:focus {
+    outline: none;
+    border-color: #1a73e8;
+    box-shadow: 0 0 0 2px rgba(26, 115, 232, 0.1);
+}
+
+.form-row {
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: 1rem;
+}
+
+.form-check {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+}
+
+.form-check input[type="checkbox"] {
+    width: auto;
+}
+
+.form-check label {
+    display: inline;
+    margin-bottom: 0;
+    font-weight: normal;
+}
+
+/* Buttons */
+.step-actions {
+    display: flex;
+    justify-content: flex-end;
+    gap: 0.75rem;
+    margin-top: 2rem;
+    padding-top: 1.5rem;
+    border-top: 1px solid #e0e0e0;
+}
+
+.btn {
+    padding: 0.6rem 1.5rem;
+    border-radius: 4px;
+    font-size: 0.95rem;
+    font-weight: 500;
+    cursor: pointer;
+    border: none;
+    transition: background-color 0.2s;
+}
+
+.btn-primary {
+    background: #1a73e8;
+    color: white;
+}
+
+.btn-primary:hover:not(:disabled) {
+    background: #1557b0;
+}
+
+.btn-primary:disabled {
+    background: #93c5fd;
+    cursor: not-allowed;
+}
+
+.btn-outline {
+    background: transparent;
+    border: 1px solid #dadce0;
+    color: #5f6368;
+}
+
+.btn-outline:hover {
+    background: #f1f3f4;
+}
+
+.btn-secondary {
+    background: #f1f3f4;
+    color: #202124;
+    border: 1px solid #dadce0;
+}
+
+.btn-secondary:hover {
+    background: #e8eaed;
+}
+
+.btn-danger-sm {
+    background: transparent;
+    color: #d93025;
+    border: 1px solid #d93025;
+    padding: 0.25rem 0.75rem;
+    font-size: 0.8rem;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.btn-danger-sm:hover {
+    background: #fce8e6;
+}
+
+.btn-link {
+    background: none;
+    border: none;
+    color: #1a73e8;
+    cursor: pointer;
+    font-size: 0.85rem;
+    font-weight: 500;
+    padding: 0;
+}
+
+.btn-link:hover {
+    text-decoration: underline;
+}
+
+.btn-submit {
+    padding: 0.75rem 2rem;
+    font-size: 1rem;
+}
+
+/* Validation */
+.validation-error {
+    color: #d93025;
+    background: #fce8e6;
+    padding: 0.75rem 1rem;
+    border-radius: 4px;
+    margin-top: 1rem;
+    font-size: 0.9rem;
+}
+
+.field-error {
+    color: #d93025;
+    font-size: 0.8rem;
+    margin-top: 0.25rem;
+    display: block;
+}
+
+/* Work Entry & Reference Cards */
+.work-entry-card,
+.reference-card {
+    border: 1px solid #e0e0e0;
+    border-radius: 6px;
+    padding: 1.5rem;
+    margin-bottom: 1rem;
+    background: #fafafa;
+}
+
+.work-entry-header,
+.reference-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 1rem;
+}
+
+.work-entry-header h4,
+.reference-header h4 {
+    margin: 0;
+    color: #202124;
+}
+
+/* Cover Letter */
+.cover-letter-textarea {
+    min-height: 250px;
+    resize: vertical;
+}
+
+.char-count {
+    text-align: right;
+    color: #5f6368;
+    font-size: 0.8rem;
+    margin-top: 0.25rem;
+}
+
+/* Review Section */
+.review-section {
+    margin-bottom: 1.5rem;
+    padding-bottom: 1.5rem;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.review-section:last-of-type {
+    border-bottom: none;
+}
+
+.review-section-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-section-header h3 {
+    margin: 0;
+    font-size: 1.1rem;
+    color: #202124;
+}
+
+.review-data {
+    display: grid;
+    grid-template-columns: 120px 1fr;
+    gap: 0.5rem;
+    margin: 0;
+}
+
+.review-data dt {
+    font-weight: 500;
+    color: #5f6368;
+}
+
+.review-data dd {
+    margin: 0;
+    color: #202124;
+}
+
+.review-work-entry {
+    margin-bottom: 1rem;
+    padding: 0.75rem;
+    background: #f8f9fa;
+    border-radius: 4px;
+}
+
+.review-dates {
+    font-size: 0.85rem;
+    color: #5f6368;
+}
+
+.review-description {
+    margin-top: 0.5rem;
+    font-size: 0.9rem;
+    color: #5f6368;
+}
+
+.review-reference {
+    margin-bottom: 0.75rem;
+    padding: 0.5rem 0;
+}
+
+.review-cover-letter {
+    white-space: pre-wrap;
+    background: #f8f9fa;
+    padding: 1rem;
+    border-radius: 4px;
+    font-size: 0.9rem;
+}
+
+/* Submission Confirmation */
+.submission-confirmation {
+    text-align: center;
+    padding: 3rem 2rem;
+}
+
+.submission-confirmation h3 {
+    color: #34a853;
+    font-size: 1.5rem;
+    margin-bottom: 1rem;
+}
+
+.submission-confirmation p {
+    color: #5f6368;
+    font-size: 1.1rem;
+}
+

